# SPDX-License-Identifier: AGPL-3.0-only
import heapq

def solve(payload):
    graph = {node: set() for node in payload["nodes"]}
    indegree = dict.fromkeys(graph, 0)
    for start, end in payload["edges"]:
        if end not in graph[start]:
            graph[start].add(end)
            indegree[end] += 1
    ready = [node for node in graph if indegree[node] == 0]
    ready.sort()
    order = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for end in sorted(graph[node]):
            indegree[end] -= 1
            if indegree[end] == 0:
                ready.append(end)
    return {"order": order, "blocked": sorted(node for node in graph if indegree[node] > 0)}

